SINA_SMART["hemato1-coagulation"] = {"lecture":"hemato1-coagulation","title":"Coagulation (secondary haemostasis)","mapStatus":"auto: generated by universal.py from the lecture summary and key points; not human-reviewed","los":[{"id":"hemato1-coagulation:e0","text":"Coagulation: cascade on platelet surfaces converting fibrinogen to fibrin.","topic":"The big picture","sec":0,"importance":"core","highYield":"insufficient-source"},{"id":"hemato1-coagulation:e1","text":"Zymogens; 'a' = activated; most factors made by the liver.","topic":"Clotting factors","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"hemato1-coagulation:e2","text":"V and VIII: labile cofactors.","topic":"Clotting factors","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"hemato1-coagulation:e3","text":"Tissue factor (III): main initiator in vivo.","topic":"Clotting factors","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"hemato1-coagulation:e4","text":"Vitamin K-dependent: II, VII, IX, X, proteins C and S; warfarin blocks.","topic":"Clotting factors","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"hemato1-coagulation:e5","text":"Extrinsic: TF + VIIa; intrinsic: XII → XI → IX + VIII (tenase).","topic":"Pathways","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"hemato1-coagulation:e6","text":"Common: Xa + Va (prothrombinase) → thrombin → fibrin; XIIIa cross-links.","topic":"Pathways","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"hemato1-coagulation:e7","text":"XII deficiency: no bleeding; VIII/IX deficiency: haemophilia A/B.","topic":"Pathways","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"hemato1-coagulation:e8","text":"Cell-based: initiation, amplification, propagation, stabilisation.","topic":"Pathways","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"hemato1-coagulation:e10","text":"Citrate 3.2%, 9:1; PT (extrinsic), aPTT (intrinsic), TT, fibrinogen.","topic":"Natural inhibitors and laboratory tests","sec":3,"importance":"core","highYield":"insufficient-source"},{"id":"hemato1-coagulation:e9","text":"Antithrombin (+ heparin); protein C + S (Va, VIIIa); TFPI (TF-VIIa).","topic":"Natural inhibitors and laboratory tests","sec":3,"importance":"core","highYield":"insufficient-source"}],"vmap":{},"mlevel":{"f6g00":"a","otormk":"a","oktupd":"a","19a1yg8":"a","1uvmyce":"a","1ni89n8":"a","1eqyial":"a","1j6tzcr":"a","wjom8e":"a","1o2vxez":"a","2k3o1q":"a","aqfi6r":"a","1jjrg4v":"a","mqs7gn":"a","13d6zmu":"a"},"mapCounts":{"verified":0,"auto":15,"ambiguous":0,"missing":0},"mrules":[],"items":[],"experimental":[],"status":{},"difficulty":{},"expl":{"hemato1-coagulation:e0":{"s":0,"u":["Coagulation: cascade on platelet surfaces converting fibrinogen to fibrin.","Coagulation (secondary haemostasis) is a cascade in which inactive enzymes are activated and in turn activate others: plasma proteins, tissue factor and calcium interact on the platelet surface to convert soluble fibrinogen into insoluble fibrin , the 'glue' that stabilises the platelet plug."],"dp":[]},"hemato1-coagulation:e1":{"s":1,"u":["Zymogens; 'a' = activated; most factors made by the liver.","Most procoagulants and anticoagulants are made by the liver (except factors III and IV)."],"dp":[]},"hemato1-coagulation:e2":{"s":1,"u":["V and VIII: labile cofactors.","Factors V and VIII are cofactors, called labile factors (lost in stored blood).","Phospholipids localise reactions and bind enzyme-cofactor complexes."],"dp":[]},"hemato1-coagulation:e3":{"s":1,"u":["Tissue factor (III): main initiator in vivo.","Tissue factor (III) : membrane glycoprotein in the vessel media, adventitia and fibroblasts (and on monocytes), hidden from blood until injury; the main initiator in vivo ; also expressed in sepsis, malignancy and inflammation (hypercoagulable states).","Most procoagulants and anticoagulants are made by the liver (except factors III and IV)."],"dp":[]},"hemato1-coagulation:e4":{"s":1,"u":["Vitamin K-dependent: II, VII, IX, X, proteins C and S; warfarin blocks.","Vitamin K-dependent factors: II, VII, IX, X and the inhibitors proteins C and S ; vitamin K adds calcium-binding groups; without it (deficiency or warfarin ) inactive proteins (PIVKA) are released."],"dp":[]},"hemato1-coagulation:e5":{"s":2,"u":["Extrinsic: TF + VIIa; intrinsic: XII → XI → IX + VIII (tenase).","Classic model : the extrinsic pathway starts when tissue factor meets blood and binds VIIa ; the intrinsic pathway starts when XII binds a negatively charged surface (with prekallikrein and HMWK), activating XI, then IX, which with VIII forms the tenase complex (IXa, VIIIa, Ca²⁺, phospholipid) activating X; the common pathway : Xa + Va , Ca²⁺ and phospholipid form the prothrombinase complex converting prothrombin to thrombin , which cleaves fibrinogen to fibrin and activates XIII , cross-linking fibrin.","Cell-based model (in vivo): initiation (TF-VIIa activates IX and X; a little thrombin), amplification (thrombin activates V, VIII, XI and platelets), propagation (tenase and prothrombinase on platelet surfaces generate a burst of thrombin), stabilisation (XIIIa cross-links fibrin)."],"dp":[]},"hemato1-coagulation:e6":{"s":2,"u":["Common: Xa + Va (prothrombinase) → thrombin → fibrin; XIIIa cross-links.","Cell-based model (in vivo): initiation (TF-VIIa activates IX and X; a little thrombin), amplification (thrombin activates V, VIII, XI and platelets), propagation (tenase and prothrombinase on platelet surfaces generate a burst of thrombin), stabilisation (XIIIa cross-links fibrin).","Classic model : the extrinsic pathway starts when tissue factor meets blood and binds VIIa ; the intrinsic pathway starts when XII binds a negatively charged surface (with prekallikrein and HMWK), activating XI, then IX, which with VIII forms the tenase complex (IXa, VIIIa, Ca²⁺, phospholipid) activating X; the common pathway : Xa + Va , Ca²⁺ and phospholipid form the prothrombinase complex converting prothrombin to thrombin , which cleaves fibrinogen to fibrin and activates XIII , cross-linking fibrin."],"dp":[]},"hemato1-coagulation:e7":{"s":2,"u":["XII deficiency: no bleeding; VIII/IX deficiency: haemophilia A/B.","This model explains laboratory tests but not bleeding: lacking XII, prekallikrein or HMWK causes no bleeding , and XI deficiency (haemophilia C) is mild, while VIII and IX deficiencies ( haemophilia A and B ) bleed badly."],"dp":[{"h":"Why haemophilia patients cannot use the 'other pathway'","t":"In the old two-pathway picture, a patient lacking factor VIII should clot through the extrinsic route. In reality, TF-VIIa makes only a small amount of thrombin; a large, sustained burst requires the tenase complex (IXa + VIIIa) on activated platelets during propagation. Without VIII or IX there is no burst, so clots are weak and bleeding into joints and muscles follows, while XII deficiency, which is not needed in vivo, causes no bleeding at all. Source: the lecture's cell-based model of coagulation."}]},"hemato1-coagulation:e8":{"s":2,"u":["Cell-based: initiation, amplification, propagation, stabilisation.","Cell-based model (in vivo): initiation (TF-VIIa activates IX and X; a little thrombin), amplification (thrombin activates V, VIII, XI and platelets), propagation (tenase and prothrombinase on platelet surfaces generate a burst of thrombin), stabilisation (XIIIa cross-links fibrin)."],"dp":[]},"hemato1-coagulation:e10":{"s":3,"u":["Citrate 3.2%, 9:1; PT (extrinsic), aPTT (intrinsic), TT, fibrinogen.","Screening : PT (thromboplastin + calcium; extrinsic and common pathway: I, II, V, VII, X; Quick, 1935), aPTT (intrinsic and common pathway), thrombin time and fibrinogen ; then factor assays and mixing studies."],"dp":[]},"hemato1-coagulation:e9":{"s":3,"u":["Antithrombin (+ heparin); protein C + S (Va, VIIIa); TFPI (TF-VIIa).","TFPI (from endothelium) blocks TF-VIIa.","Protein C (vitamin K-dependent, activated by thrombin) with its cofactor protein S inactivates Va and VIIIa ."],"dp":[]}},"meta":{"f6g00":{"a":"recall","vg":"hemato1-coagulation:e0/recall/1"},"otormk":{"a":"recall","vg":"hemato1-coagulation:e2/recall/1"},"oktupd":{"a":"recall","vg":"hemato1-coagulation:e3/recall/1"},"19a1yg8":{"a":"recall","vg":"hemato1-coagulation:e4/recall/1"},"1uvmyce":{"a":"recall","vg":"hemato1-coagulation:e4/recall/2"},"1ni89n8":{"a":"recall","vg":"hemato1-coagulation:e5/recall/1"},"1eqyial":{"a":"recall","vg":"hemato1-coagulation:e6/recall/1"},"1j6tzcr":{"a":"recall","vg":"hemato1-coagulation:e6/recall/2"},"wjom8e":{"a":"recall","vg":"hemato1-coagulation:e7/recall/1"},"1o2vxez":{"a":"recall","vg":"hemato1-coagulation:e7/recall/2"},"2k3o1q":{"a":"recall","vg":"hemato1-coagulation:e9/recall/1"},"aqfi6r":{"a":"recall","vg":"hemato1-coagulation:e9/recall/2"},"1jjrg4v":{"a":"recall","vg":"hemato1-coagulation:e1/recall/1"},"mqs7gn":{"a":"recall","vg":"hemato1-coagulation:e10/recall/1"},"13d6zmu":{"a":"recall","vg":"hemato1-coagulation:e10/recall/2"}},"explRev":"0e1e5206295f"};
